// Authored rehearsal content: one worked stock-control example (the same sentence the voice samples speak) and the
// stage layout that defines real pointing targets. Not a generated lesson.
import type { Target, Vec3 } from './types.ts';

export const SPEECH_TEXT = 'Let us take this one step at a time. Twenty notebooks, plus twelve delivered, minus nine sold, leaves twenty three.';

/** Google Chirp 3 HD samples generated by AVATAR-001 from the sentence above; voice is independent of appearance. */
export const VOICES = [
  { id: 'en-GB-Chirp3-HD-Aoede', label: 'Aoede · English (UK)' },
  { id: 'en-US-Chirp3-HD-Kore', label: 'Kore · English (US)' },
  { id: 'en-GB-Chirp3-HD-Puck', label: 'Puck · English (UK)' },
] as const;
export type VoiceId = (typeof VOICES)[number]['id'];
export const voiceAudio = (id: VoiceId) => `/models/character/audio/${id}.mp3`;
export const voiceVisemes = (id: VoiceId) => `/models/character/audio/${id}.visemes.json`;

export const BOARD_STEPS = [
  { title: 'Opening stock', formula: '20', caption: 'The shop opens with twenty notebooks.' },
  { title: 'A delivery arrives', formula: '20 + 12 = 32', caption: 'Twelve more are delivered, so there are thirty-two.' },
  { title: 'Sales go out', formula: '32 − 9 = 23', caption: 'Nine are sold. Thirty-two minus nine leaves twenty-three.' },
] as const;

/** Board: a teaching board at the teacher's left, angled toward the front so both board targets sit within a
 *  comfortable side-forward reach. Positions are world metres (teacher at the origin, facing +Z). */
export const BOARD = { centre: [0.62, 1.3, 0.05] as Vec3, yaw: -0.85, width: 0.86, height: 0.6 };
/** Board-local centres (metres from the board centre) of the two marked areas; the texture draws them here. */
export const BOARD_SPOTS = { formula: [-0.12, 0.05] as [number, number], answer: [-0.2, -0.16] as [number, number] };

function onBoard(x: number, y: number): { position: Vec3; normal: Vec3 } {
  const [cx, cy, cz] = BOARD.centre;
  const c = Math.cos(BOARD.yaw), s = Math.sin(BOARD.yaw);
  const z = 0.022;
  return {
    position: [cx + x * c + z * s, cy + y, cz - x * s + z * c],
    normal: [s, 0, c],
  };
}

export const DESK = { centre: [-0.58, 0, 0.62] as Vec3 };
/** A poster on an easel to the teacher's right, beyond arm's reach (ray pointing). */
export const EASEL = { centre: [-1.45, 1.5, 0.15] as Vec3, yaw: 1.05 };

export const TARGETS: Target[] = [
  { id: 'formula', ...onBoard(...BOARD_SPOTS.formula) },
  { id: 'answer', ...onBoard(...BOARD_SPOTS.answer) },
  { id: 'learner-work', position: [-0.58, 0.83, 0.62], normal: [0, 1, 0] },
  { id: 'poster', position: [EASEL.centre[0] + 0.02 * Math.sin(EASEL.yaw), EASEL.centre[1] + 0.05, EASEL.centre[2] + 0.02 * Math.cos(EASEL.yaw)], normal: [Math.sin(EASEL.yaw), 0, Math.cos(EASEL.yaw)] },
];

export const TARGET_LABELS: Record<string, string> = {
  formula: 'the highlighted formula',
  answer: 'the answer box',
  'learner-work': "the learner's tablet",
  poster: 'the poster across the room',
};
